    'home.story.family.desc': 'ರಿಯಾಯಿತಿ ಸಾಲ ಯೋಜನೆಗಳ ಮೂಲಕ, ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಕುಟುಂಬಗಳು ಸ್ಥಳೀಯ ವ್ಯಾಪಾರ ಆರಂಭಿಸಲು ಮತ್ತು ಆರ್ಥಿಕ ಸ್ವಾತಂತ್ರ್ಯ ಸಾಧಿಸಲು ಸಚಿವಾಲಯ ನೆರವಾಗುತ್ತದೆ.',
