    'home.story.citizen.desc': 'ಪ್ರದರ್ಶಕ್ AI ಮತ್ತು ಸಿಎಸ್‌ಸಿ ಕೇಂದ್ರಗಳು ನಾಗರಿಕರಿಗೆ ಪಾರದರ್ಶಕ ಅರ್ಹತಾ ಪರಿಶೀಲನೆ ಮತ್ತು ಮಧ್ಯವರ್ತಿಗಳಿಲ್ಲದೆ ನೇರ ಆರ್ಥಿಕ ನೆರವು ಖಚಿತಪಡಿಸುತ್ತವೆ.',
