    'home.story.edu.title': 'ತಾಂತ್ರಿಕ ಆಕಾಂಕ್ಷೆಗಳು ಮತ್ತು ವೃತ್ತಿಪರ ಬೆಳವಣಿಗೆಗೆ ಧನಸಹಾಯ.',
