    'home.hero_title': 'சரியான அரசு நிதித் திட்டத்தைக் கண்டறியவும்',
    'home.rotate_msg_1': 'அரசு மானியக் கடன் திட்டங்கள் மற்றும் நிதி உதவிகளை ஆராயுங்கள்.',
    'home.rotate_msg_2': 'உங்கள் தகுதியைச் சரிபார்த்து, உங்கள் தேவைக்கேற்ற திட்டங்களைக் கண்டறியவும்.',
    'home.rotate_msg_3': 'கடன் விதிமுறைகள், வட்டி விகிதங்கள் மற்றும் திருப்பிச் செலுத்தும் வழிகளைப் புரிந்து கொள்ளுங்கள்.',
    'home.rotate_msg_4': 'உங்கள் தோராயமான மாதாந்திர தவணையை (EMI) எளிதாகக் கணக்கிடுங்கள்.',
    'home.rotate_msg_5': 'உங்களுக்கு அருகில் உள்ள சேனல் கூட்டாளர்களைக் கண்டறியவும்.',
    'home.rotate_msg_6': 'பிரதர்ஷக் AI உதவியாளர் மூலம் உடனடி வழிகாட்டுதல் பெறுங்கள்.',
    'home.rotate_msg_7': 'எளிய மற்றும் வெளிப்படையான முறையில் திட்டத் தகவல்களைப் பெறுங்கள்.',
    'home.rotate_msg_8': 'சேனல் கூட்டாளர்களுடன் இணைந்து அடுத்த கட்ட நடவடிக்கைகளை அறியவும்.',
    'home.story.family.cat': 'குடும்ப தொழில்முனைவு',
    'home.story.family.title': 'குடும்பத் தொழில்கள் மூலம் தன்னிறைவை வளர்த்தல்.',
    'home.story.family.desc': 'மானியக் கடன் திட்டங்கள் மூலம் விளிம்புநிலை குடும்பங்கள் உள்ளூர் சில்லறை வணிகங்களைத் தொடங்கவும் பொருளாதார சுதந்திரம் பெறவும் அமைச்சகம் உதவுகிறது.',
    'home.story.family.alt': 'வணிகத்தின் முன் கடன் ஒப்புதல் ஆவணத்துடன் நிற்கும் இந்தியக் குடும்பம்',
