    'home.story.women.desc': 'தையல் மற்றும் உற்பத்தித் துறைகளில் உள்ள பெண்களுக்கு நவீன இயந்திரங்களை வாங்க குறைந்த வட்டியில் மூலதனக் கடன் உதவி.',
    'home.story.women.alt': 'ஆடை உற்பத்தித் தொழிலில் ஈடுபட்டுள்ள இளம் இந்தியப் பெண் தொழில்முனைவோர்',
