    gu: 'SC ઉદ્યોગસાહસિકો માટે કૃષિ, ઉત્પાદન, સેવાઓ અને સંલગ્ન ક્ષેત્રોમાં ₹૫૦ લાખ સુધીના સાહસો સ્થાપવા અથવા વિસ્તારવા માટે મુખ્ય પ્રોજેક્ટ લોન.',
