    ml: 'കൃഷി, നിർമ്മാണം, സേവനങ്ങൾ എന്നീ മേഖലകളിൽ ₹50 ലക്ഷം വരെയുള്ള വരുമാന സംരംഭങ്ങൾ ആരംഭിക്കുന്നതിന് എസ്‌സി സംരംഭകർക്കുള്ള മുൻനിര വായ്പ.',
