    kn: 'ಭಾರತದಲ್ಲಿ ಅಥವಾ ವಿದೇಶದಲ್ಲಿ ವೃತ್ತಿಪರ ಅಥವಾ ತಾಂತ್ರಿಕ ಕೋರ್ಸ್‌ಗಳನ್ನು ಕಲಿಯುವ ಎಸ್‌ಸಿ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಬೋಧನಾ ಶುಲ್ಕ, ಹಾಸ್ಟೆಲ್ ವೆಚ್ಚಗಳಿಗಾಗಿ ₹೪೦.೦೦ ಲಕ್ಷದವರೆಗೆ ಸಾಲ.',
