    bn: 'হিজড়া ব্যক্তি এবং ভিক্ষাবৃত্তিতে নিযুক্ত ব্যক্তি সহ প্রান্তিক জনগোষ্ঠীর জন্য MoSJE-এর কল্যাণ ও পুনর্বাসন কর্মসূচি। কল্যাণমূলক তথ্য ও সহায়তা প্রদান করে; এটি এনএসএফডিসি ঋণ প্রক্রিয়ার অংশ নয়।',
    gu: 'ટ્રાન્સજેન્ડર વ્યક્તિઓ અને ભિક્ષાવૃત્તિમાં સંકળાયેલી વ્યક્તિઓ સહિત હાંસિયામાં ધકેલાઈ ગયેલા લોકો માટે MoSJE નો સત્તાવાર કલ્યાણ અને પુનર્વસન કાર્યક્રમ.',
    kn: 'ತೃತೀಯಲಿಂಗಿಗಳು ಮತ್ತು ಭಿಕ್ಷಾಟನೆಯಲ್ಲಿ ತೊಡಗಿರುವ ವ್ಯಕ್ತಿಗಳು ಸೇರಿದಂತೆ ಅಂಚಿನಲ್ಲಿರುವ ವ್ಯಕ್ತಿಗಳಿಗಾಗಿ MoSJE ನ ಅಧಿಕೃತ ಕಲ್ಯಾಣ ಮತ್ತು ಪುನರ್ವಸತಿ ಕಾರ್ಯಕ್ರಮ.',
    ml: 'ട്രാൻസ്‌ജെൻഡർ വ്യക്തികൾ ഉൾപ്പെടെയുള്ള പാർശ്വവൽക്കരിക്കപ്പെട്ട വിഭാഗങ്ങൾക്കായുള്ള MoSJE-യുടെ ഔദ്യോഗിക ക്ഷേമ പുനരധിവാസ പദ്ധതി.',
    od: 'ଟ୍ରାନ୍ସଜେଣ୍ଡର୍ ଏବଂ ବଞ୍ଚିତ ବ୍ୟକ୍ତିଙ୍କ ପାଇଁ MoSJE ର ସରକାରୀ କଲ୍ୟାଣ ତଥା ପୁନର୍ବାସ କାର୍ଯ୍ୟକ୍ରମ। ଏହା କଲ୍ୟାଣକାରୀ ସୂଚନା ପ୍ରଦାନ କରେ; ଏହା NSFDC ଋଣ ପ୍ରକ୍ରିୟାର ଅଂଶ ନୁହେଁ।',
