    ta: 'திருநங்கைகள் உட்பட விளிம்புநிலை மக்களுக்கான MoSJE அமைச்சகத்தின் அதிகாரப்பூர்வ நலவாழ்வு மற்றும் மறுவாழ்வுத் திட்டம்.',
    te: 'ట్రాన్స్‌జెండర్లు మరియు నిరుపేద వ్యక్తులు సహా అట్టడుగు వర్గాల వ్యక్తుల కోసం MoSJE అధికారిక సంక్షేమ మరియు పునరావాస కార్యక్రమం. సంక్షేమ సమాచారం మరియు మద్దతును అందిస్తుంది; ఇది NSFDC రుణ ప్రక్రియలో భాగం కాదు.',
