    ml: 'പുതിയ സംരംഭങ്ങൾക്കായി എസ്‌സി/എസ്ടി, വനിതാ സംരംഭകർക്ക് ₹10 ലക്ഷം മുതൽ ₹1 കോടി വരെ ബാങ്ക് വായ്പ നൽകുന്ന ധനമന്ത്രാലയത്തിന്റെ ദേശീയ പദ്ധതി. വാണിജ്യ ബാങ്കുകൾ നേരിട്ട് വിതരണം ചെയ്യുന്നു.',
